// Build one consolidated statement per customer.
// Mode: Run Once for All Items.
//
// $input carries the statement_log rows (from Read the statement log) - the
// log doubles as the resend guard. Invoice rows come via $() from the
// earlier node.

const cfg = $('Settings').first().json;
const rows = $('Get open invoices').all().map(i => i.json);
const logRows = $input.all().map(i => i.json);

// Today in the WORKFLOW timezone.
// Do not use new Date() here - the Code node ignores the workflow timezone
// and would use the host clock instead.
const nowTz = $now;
const today = new Date(nowTz.year, nowTz.month - 1, nowTz.day);

// Closed states are matched exactly, after trimming and lowercasing.
// Anything not on this list is treated as OPEN and will be billed.
const CLOSED = [
  'paid', 'paid in full', 'payment received', 'void', 'cancelled', 'canceled',
  'refunded', 'draft', 'closed', 'written off', 'complete', 'completed'
];

// An unedited Settings node must fail loudly, not brand real emails with
// 'Your Business Name'. sheetUrl already fails loudly on its own; the two
// name fields would otherwise fail in the worst place - the customer's inbox.
const bn = String(cfg.businessName == null ? '' : cfg.businessName).trim();
const yn = String(cfg.yourName == null ? '' : cfg.yourName).trim();
if (!bn || bn === 'Your Business Name' || !yn || yn === 'Your Name') {
  throw new Error('Open the Settings node and replace the placeholder business name / your name before running.');
}

const symbol = String(cfg.currencySymbol || '$');

// An untouched reply-to placeholder must not leak into mail headers. With no
// Reply-To at all, replies simply go to the Gmail account that sent the mail
// (the Gmail node omits the header when this is empty).
const replyToRaw = String(cfg.yourEmail == null ? '' : cfg.yourEmail).trim();
const replyTo = (replyToRaw.indexOf('@') !== -1 && !replyToRaw.toLowerCase().endsWith('@example.com')) ? replyToRaw : '';
const minBalance = Number(cfg.minBalanceToSend) > 0 ? Number(cfg.minBalanceToSend) : 0;

// Parse a due date as a LOCAL calendar date.
// new Date('YYYY-MM-DD') parses as UTC midnight, which shifts the day backwards
// for anyone west of UTC and makes every ageing number wrong by one - so the
// ISO form is taken apart by hand instead.
// The fallback matters just as much: Google Sheets hands a real date cell back
// the way it is DISPLAYED ('7/15/2026', or a full timestamp), not as ISO.
// Slash dates are read in US month/day/year order (the way Sheets displays
// them by default). '15/7/2026' fails that parse and the row is skipped and
// counted; '5/7/2026' cannot be told apart from May 7 and is read as US
// order - the sticky tells the buyer exactly that, and that plain-text ISO
// is the reliable path.
function parseLocalDate(v) {
  if (v instanceof Date) return new Date(v.getFullYear(), v.getMonth(), v.getDate());
  const s = String(v == null ? '' : v).trim();
  if (s === '') return null;

  const head = s.split(' ')[0].split('T')[0];
  const p = head.split('-');
  if (p.length >= 3) {
    const y = Number(p[0]);
    const m = Number(p[1]);
    const d = Number(p[2]);
    if (Number.isFinite(y) && Number.isFinite(m) && Number.isFinite(d) && y >= 1000) {
      const dt = new Date(y, m - 1, d);
      // Round-trip check so 2026-02-30 is rejected instead of rolling into March.
      if (dt.getFullYear() === y && dt.getMonth() === m - 1 && dt.getDate() === d) return dt;
      return null;
    }
  }

  const parsed = new Date(s);
  if (isNaN(parsed.getTime())) return null;
  return new Date(parsed.getFullYear(), parsed.getMonth(), parsed.getDate());
}

// Read an amount without a regex. Understands '1,250.00', '$1,250.00',
// '9.500,50' (European) and '(1,250.00)' (accounting negative).
function toAmount(v) {
  if (typeof v === 'number') return Number.isFinite(v) ? v : NaN;
  const s = String(v == null ? '' : v).trim();
  if (s === '') return NaN;

  const negative = (s.indexOf('(') !== -1 && s.indexOf(')') !== -1) || s.indexOf('-') !== -1;

  let kept = '';
  for (const ch of s) {
    if ((ch >= '0' && ch <= '9') || ch === '.' || ch === ',') kept += ch;
  }
  if (kept === '') return NaN;

  const lastDot = kept.lastIndexOf('.');
  const lastComma = kept.lastIndexOf(',');
  let decimalAt = -1;
  if (lastDot !== -1 && lastComma !== -1) {
    // Whichever separator comes last is the decimal one.
    decimalAt = Math.max(lastDot, lastComma);
  } else if (lastComma !== -1) {
    // Only commas: decimal separator when one or two digits follow
    // ('9,50' and the one-decimal European form '2,5' alike).
    if (kept.length - lastComma === 2 || kept.length - lastComma === 3) decimalAt = lastComma;
  } else if (lastDot !== -1) {
    // Only dots: '1.250' is ambiguous, so treat 3 trailing digits as thousands.
    if (kept.length - lastDot !== 4) decimalAt = lastDot;
  }

  const intPart = decimalAt === -1 ? kept : kept.slice(0, decimalAt);
  const fracPart = decimalAt === -1 ? '' : kept.slice(decimalAt + 1);

  let digitsInt = '';
  for (const ch of intPart) { if (ch >= '0' && ch <= '9') digitsInt += ch; }
  let digitsFrac = '';
  for (const ch of fracPart) { if (ch >= '0' && ch <= '9') digitsFrac += ch; }
  if (digitsInt === '' && digitsFrac === '') return NaN;

  const n = Number((digitsInt === '' ? '0' : digitsInt) + (digitsFrac === '' ? '' : '.' + digitsFrac));
  if (!Number.isFinite(n)) return NaN;
  return negative ? -n : n;
}

function money(n) {
  return symbol + Number(n).toFixed(2);
}

function esc(v) {
  return String(v == null ? '' : v)
    .split('&').join('&amp;')
    .split('<').join('&lt;')
    .split('>').join('&gt;')
    .split('"').join('&quot;');
}

const groups = new Map();
const seenInvoices = new Set();
let skipped = 0;

for (const r of rows) {
  const email = String(r.customer_email == null ? '' : r.customer_email).trim();
  const status = String(r.status == null ? '' : r.status).trim().toLowerCase();
  const amount = toAmount(r.amount);
  const due = parseLocalDate(r.due_date);

  // Skip anything we cannot legitimately bill on. Counted, never silent.
  if (!email || email.indexOf('@') === -1) { skipped++; continue; }
  if (CLOSED.indexOf(status) !== -1) { skipped++; continue; }
  if (!Number.isFinite(amount) || amount <= 0) { skipped++; continue; }
  if (!due) { skipped++; continue; }

  // A duplicated ledger row must not double a customer's total. Blank ids
  // are left alone - they cannot be told apart safely.
  const invId = String(r.invoice_id == null ? '' : r.invoice_id).trim();
  if (invId) {
    const dupKey = email.toLowerCase() + '|' + invId;
    if (seenInvoices.has(dupKey)) { skipped++; continue; }
    seenInvoices.add(dupKey);
  }

  // round, not floor - a DST change mid-period must not shift the bucket.
  const days = Math.round((today - due) / 86400000);

  let bucket;
  if (days <= 0) bucket = 'Not yet due';
  else if (days <= 30) bucket = '1-30 days';
  else if (days <= 60) bucket = '31-60 days';
  else if (days <= 90) bucket = '61-90 days';
  else bucket = '90+ days';

  const key = email.toLowerCase();
  if (!groups.has(key)) {
    const nm = String(r.customer_name == null ? '' : r.customer_name).trim();
    groups.set(key, { name: nm || email, email: email, lines: [] });
  }
  groups.get(key).lines.push({
    invoice_id: invId,
    invoice_date: String(r.invoice_date == null ? '' : r.invoice_date).trim(),
    due_date: String(r.due_date == null ? '' : r.due_date).trim(),
    amount: amount,
    days: days,
    bucket: bucket
  });
}

const BUCKETS = ['Not yet due', '1-30 days', '31-60 days', '61-90 days', '90+ days'];
const out = [];
const period = nowTz.toFormat('LLLL yyyy');
const asOf = nowTz.toFormat('yyyy-MM-dd');

// Resend guard: any customer already logged as sent for this period is
// dropped here. Failed sends are NOT in this set, so re-running the
// workflow retries exactly the customers whose email did not go out.
const sentThisPeriod = new Set();
for (const lr of logRows) {
  const em = String(lr.customer_email == null ? '' : lr.customer_email).trim().toLowerCase();
  const pd = String(lr.statement_period == null ? '' : lr.statement_period).trim();
  const st = String(lr.send_status == null ? '' : lr.send_status).trim().toLowerCase();
  if (em && st === 'sent' && pd === period) sentThisPeriod.add(em);
}

for (const g of groups.values()) {
  if (sentThisPeriod.has(g.email.toLowerCase())) continue;
  const total = g.lines.reduce((s, l) => s + l.amount, 0);
  if (total < minBalance) { skipped += g.lines.length; continue; }

  // Oldest debt first.
  g.lines.sort((a, b) => b.days - a.days);

  const lineRows = g.lines.map(l =>
    '<tr><td>' + esc(l.invoice_id) + '</td><td>' + esc(l.invoice_date) + '</td><td>' + esc(l.due_date) +
    '</td><td align="right">' + money(l.amount) + '</td><td>' + esc(l.bucket) + '</td></tr>'
  ).join('');

  const ageingRows = BUCKETS
    .map(b => ({ label: b, sum: g.lines.filter(l => l.bucket === b).reduce((s, l) => s + l.amount, 0) }))
    .filter(x => x.sum > 0)
    .map(x => '<tr><td>' + esc(x.label) + '</td><td align="right">' + money(x.sum) + '</td></tr>')
    .join('');

  const html =
    '<p>Hi ' + esc(g.name) + ',</p>' +
    '<p>Here is your account statement with ' + esc(cfg.businessName) + ', as of ' + esc(asOf) + '.</p>' +
    '<table border="1" cellpadding="6" cellspacing="0">' +
    '<thead><tr><th>Invoice</th><th>Invoiced</th><th>Due date</th><th>Amount</th><th>Age</th></tr></thead>' +
    '<tbody>' + lineRows + '</tbody></table>' +
    '<p><b>Total outstanding: ' + money(total) + '</b></p>' +
    '<table border="1" cellpadding="6" cellspacing="0">' +
    '<thead><tr><th>Age</th><th>Amount</th></tr></thead>' +
    '<tbody>' + ageingRows + '</tbody></table>' +
    '<p>If anything here looks wrong, or you have already sent payment, just reply to this email and we will check it.</p>' +
    '<p>Thank you,<br>' + esc(cfg.yourName) + '<br>' + esc(cfg.businessName) + '</p>';

  out.push({
    json: {
      customer_name: g.name,
      customer_email: g.email,
      subject: 'Statement of account - ' + String(cfg.businessName) + ' - ' + period,
      html: html,
      reply_to: replyTo,
      invoice_count: g.lines.length,
      total_due: Number(total.toFixed(2)),
      statement_period: period,
      run_skipped_rows: 0
    }
  });
}

// Stamp the run-level skipped count onto every statement so it reaches the log.
// This is a whole-run figure repeated per row, not a per-customer count.
for (const o of out) {
  o.json.run_skipped_rows = skipped;
}

return out;

// Pair each Gmail response with the statement that produced it.
// Gmail preserves input order 1:1, so index pairing is safe here.
// Mode: Run Once for All Items.

const statements = $('Build statements').all();
const sent = $input.all();
const stamp = $now.toFormat('yyyy-MM-dd HH:mm');

return sent.map((item, i) => {
  const s = statements[i] ? statements[i].json : {};
  const j = item.json == null ? {} : item.json;

  // The Gmail node is set to carry on past a failure, so a bad address costs
  // one customer rather than the whole run - and the failure still gets logged.
  const messageId = j.id == null ? '' : String(j.id);

  return {
    json: {
      sent_at: stamp,
      customer_name: s.customer_name == null ? '' : s.customer_name,
      customer_email: s.customer_email == null ? '' : s.customer_email,
      statement_period: s.statement_period == null ? '' : s.statement_period,
      invoice_count: s.invoice_count == null ? 0 : s.invoice_count,
      total_due: s.total_due == null ? 0 : s.total_due,
      skipped_rows: s.run_skipped_rows == null ? 0 : s.run_skipped_rows,
      send_status: messageId === '' ? 'failed' : 'sent',
      message_id: messageId,
      thread_id: j.threadId == null ? '' : String(j.threadId)
    }
  };
});
